export function ArmyLogo({ className = "size-6" }: { className?: string }) {
  return (
    <svg 
      viewBox="0 0 107.84 102.69" 
      fill="currentColor" 
      className={className} 
      aria-label="U.S. Army"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        fillRule="evenodd"
        d="M 54.37 0 L 42.06 39.38 L 0 39.6 L 34.01 63.09 L 21.48 102.46 L 54.14 78.98 L 87.93 102.69 L 75.18 63.09 L 107.84 39.6 L 67.11 39.6 Z M 54.15 13.65 L 62.65 44.3 L 93.53 44.3 L 68.91 62.19 L 79.66 91.06 L 53.7 72.49 L 30.42 90.38 L 39.6 61.08 L 15.88 44.07 L 45.86 44.3 Z"
      />
    </svg>
  )
}

